/**
 * Generates src/environments/runtime-config.ts from environment variables
 * (or from frontend/.env for local development). Runs automatically before
 * `npm start` / `npm run build`. The generated file is git-ignored.
 *
 * Only PUBLIC values belong here: the Supabase URL and anon (publishable) key
 * are designed to be exposed to browsers and are protected by Row Level Security.
 * Never put the service-role key in the frontend.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const envFile = join(root, '.env');

const fileVars = {};
if (existsSync(envFile)) {
  for (const line of readFileSync(envFile, 'utf8').split(/\r?\n/)) {
    const m = /^\s*([A-Z0-9_]+)\s*=\s*(.*)\s*$/.exec(line);
    if (m && !line.trim().startsWith('#')) fileVars[m[1]] = m[2].replace(/^['"]|['"]$/g, '');
  }
}
const get = (k, fallback = '') => process.env[k] ?? fileVars[k] ?? fallback;

const config = {
  supabaseUrl: get('LIFESYNC_SUPABASE_URL'),
  supabaseAnonKey: get('LIFESYNC_SUPABASE_ANON_KEY'),
  apiUrl: get('LIFESYNC_API_URL', 'http://localhost:3000/api').replace(/\/$/, ''),
  appUrl: get('LIFESYNC_APP_URL', 'http://localhost:8100').replace(/\/$/, ''),
};

if (get('LIFESYNC_SUPABASE_SERVICE_ROLE_KEY') || /service_role/.test(config.supabaseAnonKey)) {
  console.error('Refusing to build: a service-role key must never be bundled into the frontend.');
  process.exit(1);
}

const missing = Object.entries(config).filter(([, v]) => !v).map(([k]) => k);
if (missing.length) {
  console.warn(`[set-env] Missing configuration: ${missing.join(', ')}. The app will show a setup screen.`);
}

const out = `// AUTO-GENERATED by scripts/set-env.mjs, do not edit or commit.
export const runtimeConfig = ${JSON.stringify(config, null, 2)} as const;
`;
writeFileSync(join(root, 'src/environments/runtime-config.ts'), out);
console.log(`[set-env] Wrote runtime-config.ts (api: ${config.apiUrl})`);
